python.solution:
def flatten(payload):
    if not payload:
        return {}
    out = {}

    def walk(node, prefix):
        if isinstance(node, dict):
            if not node:
                out[prefix] = None
                return
            for k, v in node.items():
                walk(v, f"{prefix}.{k}" if prefix else str(k))
        elif isinstance(node, list):
            if not node:
                out[prefix] = None
                return
            for i, v in enumerate(node):
                walk(v, f"{prefix}.{i}" if prefix else str(i))
        else:
            out[prefix] = node

    walk(payload, "")
    return out

